  'Type it at “Sign in with password” instead of your profile name. We never send anything to it; a forgotten password is still reset by your admin.': '"비밀번호로 로그인"에서 프로필 이름 대신 입력하세요. 이 주소로는 아무것도 보내지 않으며, 비밀번호를 잊으면 여전히 관리자가 재설정합니다.',
  'E-mail address': '이메일 주소',
