  'Use at least {0} characters.': '최소 {0}자 이상 사용하세요.',
  'That password is too long.': '비밀번호가 너무 깁니다.',
  'That password is too easy to guess. Try a longer one, or a few random words strung together.': '추측하기 너무 쉬운 비밀번호입니다. 더 긴 비밀번호나 무작위 단어 몇 개를 이어 붙여 보세요.',
