  'Your passkey could not be confirmed.': '패스키를 확인할 수 없습니다.',
  'This password is the only way into your profile, so it cannot be removed.': '이 비밀번호는 프로필에 들어갈 수 있는 유일한 방법이므로 제거할 수 없습니다.',
  'That reset code is wrong or has expired. Ask your admin for a new one.': '재설정 코드가 틀렸거나 만료되었습니다. 관리자에게 새 코드를 요청하세요.',
