  'Confirm with a passkey': '패스키로 확인',
  'Confirmed. Now create the new passkey; your browser will ask where to keep it.': '확인되었습니다. 이제 새 패스키를 만드세요. 브라우저가 어디에 보관할지 물어봅니다.',
  'Copy link': '링크 복사',
  'Create a passkey on this device for the profile “{0}”. It signs you in here from now on.': '이 기기에서 "{0}" 프로필용 패스키를 만드세요. 앞으로 여기서는 이 패스키로 로그인합니다.',
  'Enter the code from your other device.': '다른 기기의 코드를 입력하세요.',
  'For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.': '이 기기, 보안 키, 비밀번호 관리자 또는 브라우저 자체 QR 코드를 통한 휴대폰용입니다. 먼저 본인인지 확인하세요.',
  'It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.': '더 이상 이 프로필에 로그인할 수 없습니다. 이 패스키로 이미 로그인된 기기는 로그인 상태로 남습니다. 분실했다면 "모든 기기에서 로그아웃"을 사용하세요.',
  'It is your only way in, so it cannot be removed until there is another.': '유일한 로그인 수단이므로 다른 수단이 생길 때까지 제거할 수 없습니다.',
  'Last used {0}': '마지막 사용 {0}',
  'Make a new code': '새 코드 만들기',
  'Name, e.g. Work laptop': '이름, 예: 업무용 노트북',
  'None yet. Add one and sign in without your password.': '아직 없어요. 하나 추가하면 비밀번호 없이 로그인할 수 있어요.',
  'Passkey added': '패스키 추가됨',
