  'the configured AI provider': '설정된 AI 제공자',
  'Your name, your sign-in details and everything else about your account stay here. Other people’s data is never included.': '이름, 로그인 정보 등 계정에 관한 나머지는 모두 여기 남습니다. 다른 사람의 데이터는 절대 포함되지 않습니다.',
  'You can turn this off at any time, which also discards anything the Coach is holding for you.': '언제든 끌 수 있으며, 그러면 코치가 보관 중인 내용도 함께 삭제됩니다.',
  'The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.': '코치는 의사나 물리치료사가 아닙니다. 통증이 있다면 전문가에게 문의하세요.',
