  'Disconnected. Back to local-only': '연결 해제됨. 로컬 전용으로 돌아감',
  'Connect to my server': '내 서버에 연결',
  'Sync this device to your own self-hosted Gains instead.': '대신 이 기기를 직접 호스팅하는 Gains 서버와 동기화합니다.',
  'Pair the mobile app': '모바일 앱 페어링',
  'Connect the Gains app on your phone to this account.': '휴대폰의 Gains 앱을 이 계정에 연결하세요.',
  'Could not generate a code': '코드를 생성하지 못했습니다',
  'On the Gains app, choose “Connect to my server”, then enter this address and the code below. It expires in 5 minutes.': 'Gains 앱에서 "내 서버에 연결"을 선택한 다음, 이 주소와 아래 코드를 입력하세요. 5분 후 만료됩니다.',
  'Enter your server address and the code': '서버 주소와 코드를 입력하세요',
  'Connected': '연결됨',
  'Could not connect': '연결하지 못했습니다',
