  'All synced': '모두 동기화됨',
  'Waiting to sync': '동기화 대기 중',
  'Offline. The server can’t be reached': '오프라인. 서버에 연결할 수 없음',
  'Not a Gains answer (HTTP {0})': 'Gains 응답이 아님 (HTTP {0})',
  'Your server’s address answered with something other than Gains (HTTP {0}). Your changes are kept here.': '서버 주소가 Gains이 아닌 다른 응답을 보냈습니다 (HTTP {0}). 변경 사항은 이 기기에 보관됩니다.',
  'Server error (HTTP {0})': '서버 오류 (HTTP {0})',
  'Your server answered with an error (HTTP {0}). Your changes are kept here.': '서버가 오류로 응답했습니다 (HTTP {0}). 변경 사항은 이 기기에 보관됩니다.',
  'The server refuses this browser': '서버가 이 브라우저를 거부합니다',
  'Your server no longer accepts this browser. Your changes are kept here.': '서버가 더 이상 이 브라우저를 허용하지 않습니다. 변경 사항은 이 기기에 보관됩니다.',
  'This phone is no longer paired with your server. Your changes are kept here.': '이 휴대폰은 더 이상 서버와 페어링되어 있지 않습니다. 변경 사항은 이 기기에 보관됩니다.',
  'The server refuses this phone': '서버가 이 휴대폰을 거부합니다',
  'Your server no longer accepts this phone. Your changes are kept here.': '서버가 더 이상 이 휴대폰을 허용하지 않습니다. 변경 사항은 이 기기에 보관됩니다.',
  'On this phone only, not connected to a server': '이 휴대폰에만 저장, 서버에 연결되지 않음',
  'Pair again': '다시 페어링',
  'Sign in': '로그인',
  'Disconnect anyway': '그래도 연결 해제',
  'Sign out anyway': '그래도 로그아웃',
  'Couldn’t keep a copy of the changes on this device. Nothing was removed.': '이 기기에 변경 사항의 사본을 보관하지 못했습니다. 아무것도 삭제되지 않았습니다.',
  'Not everything is on your server yet': '아직 서버에 모든 내용이 있지는 않습니다',
  'Not on your server yet: {0}': '아직 서버에 없음: {0}',
  'Some changes on this device have not reached your server.': '이 기기의 일부 변경 사항이 아직 서버에 도달하지 않았습니다.',
  'Try again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': '다시 시도하거나 먼저 백업을 내보내세요. 그래도 계속하면 이 기기가 이 계정으로 이 서버에 다시 연결될 때까지 변경 사항의 사본이 이 기기에 보관됩니다. 그때 다시 추가됩니다.',
  'Syncing…': '동기화 중…',
  'Try again': '다시 시도',
  'Last synced: {0}': '마지막 동기화: {0}',
  'Not synced with this server yet': '아직 이 서버와 동기화되지 않음',
  'Server & sync': '서버 및 동기화',
  'Signed in as {0}': '{0}(으)로 로그인됨',
  'Sync now': '지금 동기화',
  'Your changes are kept here, and merged into your account once it is paired again.': '변경 사항은 이 기기에 보관되며, 다시 페어링하면 계정에 병합됩니다.',
  'Your changes are kept here, and merged into your account once you are signed in again.': '변경 사항은 이 기기에 보관되며, 다시 로그인하면 계정에 병합됩니다.',
  'Changes kept for {0}': '{0}의 보관된 변경 사항',
  'Added back when this device connects as that account again.': '이 기기가 해당 계정으로 다시 연결되면 다시 추가됩니다.',
  'The changes your server has not seen are kept on this device, and added back when it connects as this account again.': '서버에 아직 없는 변경 사항은 이 기기에 보관되며, 이 계정으로 다시 연결되면 다시 추가됩니다.',
  'This phone switches back to local-only and its copy of your account is removed. First it checks that your server has every change. If not, you choose what happens to them.': '이 휴대폰은 로컬 모드로 돌아가고, 계정 사본이 휴대폰에서 삭제됩니다. 먼저 서버에 모든 변경 사항이 있는지 확인하며, 없으면 어떻게 할지 직접 선택합니다.',
  'Your data is removed from this browser; your profile on the server keeps it. First it checks that the server has every change. If not, you choose what happens to them.': '데이터가 이 브라우저에서 삭제되며, 서버의 프로필에는 그대로 남습니다. 먼저 서버에 모든 변경 사항이 있는지 확인하며, 없으면 어떻게 할지 직접 선택합니다.',
  'Signs this profile out on every device, including this one. Phones paired with it are disconnected and have to be paired again. Your passkeys keep working, so you can sign in with them again anytime.': '이 기기를 포함한 모든 기기에서 이 프로필을 로그아웃합니다. 이 프로필과 페어링된 휴대폰은 연결이 해제되며 다시 페어링해야 합니다. 패스키는 계속 작동하므로 언제든 다시 로그인할 수 있습니다.',
  '{0} change': '변경 {0}개',
  '{0} changes': '변경 {0}개',
