  'Planned sessions start from': '계획된 세션의 시작 기준',
  'The routine’s sets and reps. Your history decides the weight.': '루틴의 세트와 횟수. 무게는 기록에 따라 정해집니다.',
  'Your last session': '지난 세션',
  'The reps you logged last time in that routine, carried over.': '그 루틴에서 지난번에 기록한 횟수를 그대로 가져옵니다.',
  'Plan changed, so starting from your new target.': '계획이 바뀌어서 새 목표부터 시작해요.',
  'First time in this routine, so starting from its own target.': '이 루틴은 처음이라 루틴의 목표부터 시작해요.',
  'No weight logged last time. Enter what you lift and progression takes it from there.': '지난번에 기록된 무게가 없어요. 드는 무게를 입력하면 거기서부터 진행해요.',
  'Plan: {0}': '계획: {0}',
  'today {0}': '오늘 {0}',
  'reps from your last session': '지난 세션의 횟수',
  'Save as routine?': '루틴으로 저장할까요?',
  'Save as routine': '루틴으로 저장',
  'Create an independent routine from these exercise targets. Your workout history is kept.': '이 운동 목표로 독립 루틴을 만듭니다. 운동 기록은 그대로 유지됩니다.',
  'Pause': '일시정지',
  'Keep timing after target': '목표 시간 후에도 계속 측정',
  'Timed sets continue up to 15 extra minutes. Tap Done to log the actual duration.': '시간 제한 세트는 최대 15분 추가로 계속됩니다. 실제 시간을 기록하려면 완료를 누르세요.',
  'Edit workout': '운동 편집',
  'Workout updated': '운동이 업데이트됨',
  'Save workout changes?': '운동 변경 사항을 저장할까요?',
  'Save your edits to this workout, or keep the original record.': '이 운동의 변경 사항을 저장하거나 원래 기록을 유지하세요.',
  'Save changes': '변경 사항 저장',
  "Don't save": '저장하지 않기',
  'Keep editing': '계속 편집',
  'This workout was deleted on another device. Your edits are still here.': '이 운동은 다른 기기에서 삭제되었습니다. 편집 내용은 여기에 남아 있습니다.',
  'Close editor': '편집기 닫기',
  // --- demo build (v1.3.7) ---
  'A pull for every press, so the shoulders stay balanced.': '미는 운동마다 당기는 운동을 하나씩. 그래야 어깨 균형이 유지돼요.',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': '입력한 장비에 맞춰 주 3회 세션에 걸쳐 도는 2일 로테이션이에요. 복합 운동을 먼저, 미는 운동마다 당기는 운동 하나씩, 그리고 어떤 부위도 2주 동안 훈련 없이 지나가지 않도록 날마다 충분히 겹치게 했어요.',
  'Based on the training already in this demo profile.': '이 데모 프로필에 이미 있는 훈련을 바탕으로 했어요.',
  'Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.': '목표는 증량인데 체중이 4주째 제자리예요. 이건 훈련이 아니라 부엌 문제예요. 계획이 발목을 잡고 있는 게 아니에요.',
  'Demo': '데모',
  'Demo data reset': '데모 데이터를 초기화했어요',
  'Direct arm work, since you asked for it.': '요청하신 대로 팔을 직접 단련하는 운동이에요.',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': '이 운동의 메인 세트는 세 번의 세션 동안 모두 RPE 9.5 이상이었고 중량은 그대로예요. 4주 동안 동작을 바꾸면 같은 동작을 억지로 밀어붙이는 것보다 보통 더 빨리 정체기를 벗어나요.',
  'Example data, stored only in this browser. Go wild and change anything you like.': '예시 데이터이며 이 브라우저에만 저장돼요. 마음껏 이것저것 바꿔 보세요.',
  'Full body A': '전신 A',
  'Full body B': '전신 B',
  'Horizontal pressing, the other half of the session.': '수평 밀기, 세션의 나머지 절반이에요.',
  'Live demo. Everything stays in this browser.': '라이브 데모. 모든 것이 이 브라우저에만 남아요.',
  'No training history yet, so starting conservatively.': '아직 훈련 기록이 없어서 보수적으로 시작해요.',
  'Passkey sign-in, sync across your devices, your own data.': '패스키 로그인, 기기 간 동기화, 나만의 데이터.',
  'Puts the example plan, workouts and weigh-ins back the way they started.': '예시 플랜, 운동, 체중 기록을 처음 상태로 되돌려요.',
  'Reset': '초기화',
  'Reset demo data': '데모 데이터 초기화',
  'Reset demo data?': '데모 데이터를 초기화할까요?',
  'Revised as you asked. Everything you did not question is exactly as it was.': '요청하신 대로 수정했어요. 문제 삼지 않은 부분은 모두 그대로예요.',
  'Same pattern, higher reps than day A.': '같은 패턴, A일보다 반복 횟수를 늘렸어요.',
  'Self-host it in a minute →': '1분 만에 직접 호스팅하기 →',
  'Self-host Gains': 'Gains 직접 호스팅하기',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': '세션이 예정보다 15분 정도 길어지고 있어요. 이 보조 운동은 한 세트를 줄여도 잃을 게 가장 적어요.',
  'Start the demo': '데모 시작',
  'The main lower-body driver, where most of the strength comes from.': '하체의 핵심 운동으로, 힘의 대부분이 여기서 나와요.',
  'The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.': '같은 패턴, 다른 변형: 성장할 만큼 겹치고, 지루하지 않을 만큼 달라요.',
  'The two big lower-body and pressing patterns first, while you are fresh.': '힘이 있을 때 하체와 미는 운동의 두 큰 패턴을 먼저 해요.',
  'This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the Gains server, which you get by self-hosting it.': '이 데모는 예시 데이터로 브라우저 안에서만 실행돼요. 어디에도 전송되지 않아요. 패스키 로그인과 기기 간 동기화는 직접 호스팅하는 Gains 서버와 함께 제공돼요.',
  'Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.': '바꿀 만한 것 세 가지와 알아 둘 만한 것 한 가지예요. 나머지는 모두 잘 되고 있어요: 스쿼트와 당기기 모두 계획대로 늘고 있어요.',
  'Vertical pressing.': '수직 밀기.',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': '3주 연속으로 이 세션을 토요일로 옮겼어요. 매번 바꾸기보다 계획에 그렇게 적어 두는 편이 나아요.',
  'You’re in the demo': '데모 모드예요',
