  'Workouts and weigh-ins go to Health Connect when you finish or change them. Gains reads nothing back.': '운동과 체중 기록은 완료하거나 수정할 때 헬스 커넥트로 갑니다. Gains은 아무것도 읽어 오지 않습니다.',
