  'e.g. “swap the squats for split squats, and Mondays are short”': '예: “스쿼트를 스플릿 스쿼트로 바꿔 줘, 월요일은 짧게”',
  'Added before your work sets and left out of volume, records and progression. Each one closes half the gap to the work weight, and you can still change any of them mid-session.': '본세트 전에 추가되며 볼륨, 기록, 점진적 증가에는 포함되지 않아요. 하나하나가 본세트 무게와의 차이를 절반씩 좁혀 주고, 운동 중에도 언제든 바꿀 수 있어요.',
  'The app can only pair with an https:// address. Your phone blocks plain http:// before anything is even sent.': '앱은 https:// 주소로만 페어링할 수 있어요. 일반 http://는 아무것도 전송되기 전에 휴대폰이 차단해요.',
  '1RM formula': '1RM 공식',
